import { type Clock, systemClock } from "./clock.ts";

/** Port: generates entity ids (blueprint §2.2: text primary keys, UUIDv7). */
export interface IdGenerator {
  next(): string;
}

export const UUID_V7_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

/**
 * RFC 9562 UUIDv7: 48-bit Unix ms timestamp, then randomness. Ids generated by one generator
 * are strictly increasing (rand_a is used as a 12-bit counter within a millisecond, method 1
 * of RFC 9562 §6.2), so they sort by creation time, which keeps B-tree inserts cheap.
 */
export function createUuidV7Generator(options: { clock?: Clock } = {}): IdGenerator {
  const clock = options.clock ?? systemClock;
  let lastMs = -1;
  let counter = 0;

  return {
    next() {
      let ms = clock.now();
      if (ms > lastMs) {
        lastMs = ms;
        // Start the counter in the lower half so a burst has room to increment.
        counter = crypto.getRandomValues(new Uint16Array(1))[0] ?? 0;
        counter &= 0x7ff;
      } else {
        ms = lastMs;
        counter += 1;
        if (counter > 0xfff) {
          // Counter exhausted: borrow the next millisecond to stay monotonic.
          lastMs += 1;
          ms = lastMs;
          counter = 0;
        }
      }

      const bytes = crypto.getRandomValues(new Uint8Array(16));
      const view = new DataView(bytes.buffer);
      view.setUint16(0, Math.floor(ms / 2 ** 32) & 0xffff);
      view.setUint32(2, ms >>> 0);
      view.setUint16(6, 0x7000 | counter);
      bytes[8] = ((bytes[8] ?? 0) & 0x3f) | 0x80;

      const hex = Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
      return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
    },
  };
}

/** Deterministic ids for tests and fixtures: `id-000001`, `id-000002`, ... */
export function createSequentialIdGenerator(prefix = "id"): IdGenerator {
  let sequence = 0;
  return {
    next() {
      sequence += 1;
      return `${prefix}-${String(sequence).padStart(6, "0")}`;
    },
  };
}
